    "termsPageTitle": "Terms of Use",
    "termsIntroPart1": "These Terms of Use (\"Terms\") govern access to and use of the",
    "termsIntroPart2": "(the \"Dashboard\") and the Discord bot",
    "termsIntroPart3": "(together, the \"Service\"), developed and operated by Rub19 as an independent personal project. By using the Service, you agree to these Terms.",
    "termsS1Title": "1. Nature of the Service",
    "termsS1Body": "ETHONE is a personal project providing a moderation, music, ticketing and server-management bot for Discord, along with an associated web dashboard for configuring the bot and connecting third-party services (Discord, Spotify, GitHub, Google Calendar, Notion, Todoist, etc.). The Service is provided \"as is\", with no guarantee of continuous availability, and may evolve, change or be discontinued at any time without notice.",
    "termsS2Title": "2. Account and access",
    "termsS2Body": "Access to the Dashboard requires authentication (for example via Discord, or an email/password account managed by our infrastructure provider Supabase). You are responsible for keeping your credentials confidential and for any activity carried out from your account. The Bot is added to a Discord server through the official invite link provided in the Dashboard or on Discord.",
    "termsS3Title": "3. Acceptable use",
    "termsS3Intro": "You agree not to use the Service to:",
    "termsS3Item1": "violate the Terms of Use or Discord's Community Guidelines;",
    "termsS3Item2": "harass, threaten or harm others, or distribute illegal content;",
    "termsS3Item3": "attempt to bypass the Service's security, moderation or technical limits (spam, command abuse, exploiting bugs);",
    "termsS3Item4": "collect other users' data for purposes not intended by the Service.",
    "termsS3Outro": "Any confirmed abuse may lead to the Bot being suspended on a server, revocation of Dashboard access, or the removal of features, at our discretion.",
    "termsS4Title": "4. Third-party integrations",
    "termsS4Body": "The Service lets you connect third-party accounts (Discord, Spotify, GitHub, Google, Notion, Todoist, etc.) via OAuth. Each of these services remains governed by its own terms of use and privacy policy, over which we have no control. You can disconnect these integrations at any time from the Dashboard's Connections page.",
    "termsS5Title": "5. Ownership",
    "termsS5Body": "The ETHONE code, design and brand remain the property of their author. Content you create through the Service (messages, tickets, server configurations, notes, etc.) belongs to you; we do not reuse it outside the normal operation of the Service.",
    "termsS6Title": "6. Limitation of liability",
    "termsS6Body": "As the Service is a personal project provided free of charge and \"as is\", it comes with no warranty of any kind, express or implied. To the extent permitted by law, we cannot be held liable for data loss, service interruptions or indirect damages resulting from use of the Service.",
    "termsS7Title": "7. Changes",
    "termsS7Body": "These Terms may be updated as the Service evolves. The \"last updated\" date at the top of this page reflects the version in effect. Continued use of the Service after a change constitutes acceptance of the new Terms.",
    "termsS8Title": "8. Contact",
    "termsS8BodyPrefix": "For any question about these Terms, you can reach us at:",
    "termsSeeAlsoPrefix": "See also our",
    "termsSeeAlsoSuffix": ".",
    "privacyLinkText": "Privacy Policy",
    "privacyPageTitle": "Privacy Policy",
    "privacyIntroPart1": "This policy explains what data is collected when you use",
    "privacyIntroPart2": "and the Discord bot",
    "privacyIntroPart3": "(together, the \"Service\"), why, and how it is processed. ETHONE is an independent personal project; we do not sell any data and do not use it for advertising purposes.",
    "privacyS1Title": "1. Data we collect",
    "privacyS1Intro": "Depending on the features you use, we may process:",
    "privacyS1Item1Label": "Discord account",
    "privacyS1Item1Body": ": Discord ID, username, avatar, and the list of servers where you have management permissions — needed to display and configure the Bot on your servers.",
    "privacyS1Item2Label": "Bot data on a server",
    "privacyS1Item2Body": ": messages needed for moderation (reported content, sanctions, warnings), support tickets, polls, level/XP statistics, and server configuration (prefix, colors, language, enabled modules) — stored to make these features work.",
    "privacyS1Item3Label": "Third-party integrations (OAuth)",
    "privacyS1Item3Body": ": if you connect Spotify, GitHub, Google Calendar, Notion, Todoist or another service from the Connections page, we store an access token (and refresh token where applicable) to display your data from that service (e.g. the track currently playing on Spotify) — never your credentials for the third-party service itself, which remain managed directly by that service via the OAuth protocol.",
    "privacyS1Item4Label": "Dashboard preferences",
    "privacyS1Item4Body": ": theme, language, layout, tasks, notes and other content you create in the Dashboard.",
    "privacyS1Item5Label": "Technical data",
    "privacyS1Item5Body": ": IP address and basic request logs (via our Cloudflare infrastructure), for security and diagnostic purposes, kept for a limited time.",
    "privacyS2Title": "2. Where data is stored",
    "privacyS2Part1": "Account and configuration data is stored via",
    "privacyS2Part2": "(database and authentication). The Dashboard is hosted on",
    "privacyS2Part3": "and exchanges with OAuth providers go through a secure relay,",
    "privacyS2Part4": "which only shares your tokens with the relevant service. The Discord Bot runs on a dedicated private server.",
    "privacyS3Title": "3. Why we process this data",
    "privacyS3Body": "Solely to operate the Service you explicitly use: displaying your profile and servers, running the Bot's commands, showing connected integrations in the Dock/Dynamic Island, syncing your settings between the Bot and the Dashboard, and keeping the Service secure (anti-spam, anti-raid).",
    "privacyS4Title": "4. Data sharing",
    "privacyS4Intro": "We do not sell or rent your data. It is only shared with:",
    "privacyS4Item1": "the technical providers necessary for the Service to run (Supabase, Cloudflare);",
    "privacyS4Item2": "the relevant third-party service, when you use an OAuth integration you connected yourself (e.g. Discord, Spotify);",
    "privacyS4Item3": "competent authorities, only if required to do so by law.",
    "privacyS5Title": "5. Your rights",
    "privacyS5Part1": "At any time you can: disconnect an integration from the Connections page, remove the Bot from a server, or request deletion of your account and associated data by contacting us at",
    "privacyS5Part2": "We will handle any deletion request within a reasonable time.",
    "privacyS6Title": "6. Cookies and local storage",
    "privacyS6Body": "The Dashboard uses the browser's local storage (localStorage) to remember your display preferences and session, as well as technical cookies required for Supabase authentication. We do not use advertising cookies or third-party trackers.",
    "privacyS7Title": "7. Minors",
    "privacyS7Body": "The Service relies on Discord and follows its minimum age requirements. It is not intended for people who do not meet the minimum age required by Discord in their country of residence.",
    "privacyS8Title": "8. Changes",
    "privacyS8Body": "This policy may evolve along with the Service. The date at the top of this page indicates the version in effect.",
    "privacyS9Title": "9. Contact",
    "privacyS9BodyPrefix": "For any question about this policy or your data:",
    "privacySeeAlsoPrefix": "See also our",
